<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';$u=require_user($pdo);header('Cache-Control: private, no-store');header('Vary: Cookie');$id=(string)($_GET['id']??'');
$q=$pdo->prepare('SELECT * FROM moderation_reports WHERE public_id=? AND reported_by_user_id=? LIMIT 1');$q->execute([$id,$u['id']]);$r=$q->fetch();if(!$r){http_response_code(404);exit('Report not found.');}
$q=$pdo->prepare('SELECT action_type,reason,created_at FROM moderation_actions WHERE report_id=? ORDER BY id ASC');$q->execute([$r['id']]);$events=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Report status · Annotated</title><meta name="robots" content="noindex,nofollow"><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/home.php">Annotated</a><nav><a href="/notifications.php">Notifications</a><a href="/settings.php">Settings</a></nav></header><main class="panel narrow"><span class="eyebrow">REPORT STATUS</span><h1><?=h(ucwords(str_replace('_',' ',(string)$r['status'])))?></h1><p class="meta">Case <?=h($r['public_id'])?> · <?=h($r['object_type'])?> · submitted <?=h($r['created_at'])?></p><div class="card"><h3><?=h(ucwords(str_replace('_',' ',(string)$r['reason'])))?></h3><p><?=nl2br(h((string)$r['description']))?></p><?php if($r['moderator_note']):?><p><strong>Moderator note:</strong> <?=nl2br(h((string)$r['moderator_note']))?></p><?php endif?><?php if($r['resolution_action']!=='none'):?><p><strong>Resolution:</strong> <?=h(ucfirst((string)$r['resolution_action']))?></p><?php endif?></div><h2>Case history</h2><?php if(!$events):?><p class="meta">No moderator actions recorded yet.</p><?php endif?><?php foreach($events as $e):?><div class="historyItem"><strong><?=h(ucwords(str_replace('_',' ',(string)$e['action_type'])))?></strong><div class="meta"><?=h($e['created_at'])?></div><?php if($e['reason']):?><p><?=nl2br(h((string)$e['reason']))?></p><?php endif?></div><?php endforeach?></main></body></html>